WITH latest AS (SELECT id, duration_sec FROM web_events QUALIFY ROW_NUMBER() OVER (PARTITION BY page ORDER BY duration_sec DESC NULLS LAST, id) = 1) SELECT CASE WHEN duration_sec >= 506 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, COUNT(*) AS event_count, ROUND(AVG(duration_sec), 2) AS avg_duration_sec, APPROX_PERCENTILE(duration_sec, 0.5) AS duration_sec_p50, BIT_OR(duration_sec) AS duration_sec_bit_or, BIT_AND(duration_sec) AS duration_sec_bit_and FROM latest GROUP BY CASE WHEN duration_sec >= 506 THEN 'LARGE' ELSE 'SMALL' END;
